            } else {
                if (src.length > srcPos + 1 && src[srcPos + 1]) {
                    if (src[srcPos]) {
                        return 'b';
                    } else {
                        return 'a';
                    }
                } else {
                    if (src[srcPos]) {
                        return '9';
                    } else {
                        return '8';
                    }
                }
            }
        } else {
            if (src.length > srcPos + 2 && src[srcPos + 2]) {
                if (src.length > srcPos + 1 && src[srcPos + 1]) {
