                    }
                } else {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return 'd';
                    } else {
                        return 'c';
                    }
                }
            } else {
                if (src.length > srcPos + 2 && src[srcPos + 2]) {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return 'b';
                    } else {
                        return 'a';
                    }
                } else {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return '9';
                    } else {
                        return '8';
                    }
                }
            }
        } else {
            if (src.length > srcPos + 1 && src[srcPos + 1]) {
                if (src.length > srcPos + 2 && src[srcPos + 2]) {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return '7';
                    } else {
                        return '6';
                    }
                } else {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return '5';
                    } else {
                        return '4';
                    }
                }
            } else {
                if (src.length > srcPos + 2 && src[srcPos + 2]) {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return '3';
                    } else {
                        return '2';
                    }
                } else {
                    if (src.length > srcPos + 3 && src[srcPos + 3]) {
                        return '1';
                    } else {
                        return '0';
                    }
                }
            }
        }
    }

